INSERT INTO public.scenarios (
  scenario_code, subject, competency, developmental_band, difficulty,
  prompt, options, learning_objective, hint,
  irt_a, irt_b, irt_c, is_active, usage_count
) VALUES
('ENG-78-UND-01', 'English Literacy', 'understanding', '7-8', 'standard', '"While the city council heralded the arterial bypass as an overdue economic catalyst, residents in the historic merchant quarter lamented the severance of centuries-old pedestrian conduits." What constitutes the foundational tension in this account?', '[{"text":"Modern vehicular efficiency and commercial expansion versus the preservation of communal cultural heritage and pedestrian life.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"A budgetary disagreement between paving stone manufacturers and asphalt suppliers.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A dispute regarding municipal council election dates.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Disagreement among long-distance truck drivers over highway toll payment lanes.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing core thematic conflicts between modernization and historic preservation.', 'Look at what the council wanted (bypass/economic catalyst) vs what residents mourned (pedestrian conduits).', 1.25, -0.1, 0.25, true, 0),
('ENG-78-UND-02', 'English Literacy', 'understanding', '7-8', 'standard', '"To dismiss the astrophysicist''s initial sensor anomalies as instrumental noise was convenient, yet it postponed the confirmation of the exoplanet by nearly a decade." What does the author imply by describing the dismissal as "convenient"?', '[{"text":"It was coordinated to match university semester deadlines.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"It was a logistically practical and highly rigorous scientific protocol.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"It was cost-effective because computer storage drives were inexpensive.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"It was an intellectually lazy and self-serving evasion of unexpected empirical complexity.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]}]'::jsonb, 'Interpreting critical subtext and authorial irony in academic narratives.', 'Why would calling a scientific dismissal "convenient" be a criticism?', 1.3, 0.1, 0.25, true, 0),
('ENG-78-UND-03', 'English Literacy', 'understanding', '7-8', 'standard', '"The diplomat''s statement was calibrated with such microscopic ambiguity that opposing factions each left the summit convinced their non-negotiable demands had been ratified." What does this reveal about the diplomat''s strategy?', '[{"text":"The diplomat lacked sufficient grasp of the official conference working languages.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Deliberate linguistic vagueness was utilized to achieve temporary consensus without resolving the underlying dispute.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Both factions had agreed in advance to abandon all territorial claims.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The summit treaty was written in an undeciphered ancient cipher.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Deconstructing political rhetoric and strategic ambiguity.', 'Notice that opposing sides each believed they won because of the "microscopic ambiguity".', 1.35, 0.2, 0.25, true, 0),
('ENG-78-UND-04', 'English Literacy', 'understanding', '7-8', 'standard', '"Despite the tempest howling outside and thrashing the coastal pines, our small stone hearth radiated an unyielding warmth, anchoring the room against the night." What atmosphere is created by this juxtaposition?', '[{"text":"A profound sanctuary of domestic security and resilience contrasted against external violent chaos.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"A state of panic as the stone fireplace threatened to collapse under wind gusts.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"An accurate meteorological log measuring ocean gale wind vectors.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Disappointment that firewood supplies were rapidly being depleted.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing atmospheric contrast and emotional resonance in descriptive fiction.', 'Contrast the "tempest howling outside" with the "unyielding warmth, anchoring the room".', 1.3, 0, 0.25, true, 0),
('ENG-78-UND-05', 'English Literacy', 'understanding', '7-8', 'standard', '"The novel''s protagonist mistook cynical detachment for intellectual maturity, scorning empathy as a sentimental liability until isolation forced a re-evaluation." What core flaw defines the protagonist''s trajectory?', '[{"text":"An inability to comprehend basic academic texts without tutoring.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Equating emotional indifference with wisdom, which inevitably resulted in painful personal estrangement.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"A reckless ambition to acquire immense speculative fortune.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A clinical fear of traveling beyond his home city boundaries.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Evaluating character arc and psychological delusion in thematic fiction.', 'Notice how the character viewed cynicism as "intellectual maturity" and empathy as a "liability".', 1.35, 0.2, 0.25, true, 0),
('ENG-78-UND-06', 'English Literacy', 'understanding', '7-8', 'advanced', '"In describing the abandoned textile mill as a ''derelict leviathan rusting beside the stagnant canal,'' what impression does the author evoke regarding the decline of industrial manufacture?"', '[{"text":"The mill is depicted as an obsolete, decaying colossus whose once-immense power has become a stranded relic of the past.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"The factory is actively operating modern robotic loom assembly lines.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A real prehistoric marine reptile was trapped in the municipal drainage system.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The canal water was diverted to irrigate nearby botanical gardens.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing evocative metaphors and symbolic industrial decay.', 'What does comparing a mill to a "derelict leviathan" (a stranded giant monster) symbolize?', 1.4, 0.4, 0.25, true, 0),
('ENG-78-UND-07', 'English Literacy', 'understanding', '7-8', 'advanced', '"The architect insisted that true minimalism is not an austere absence of ornamentation, but the rigorous elimination of the superfluous until only pure structural necessity remains." How does this distinction redefine minimalism?', '[{"text":"As an intentional, disciplined distillation of purpose rather than a merely barren aesthetic trend.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"As an inexpensive technique to reduce the wages of structural masonry workers.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"As a mandate that all interior furniture must be manufactured from stainless steel.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"As a decorative style that requires ornate plaster moldings.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Deconstructing conceptual definitions and philosophical nuances in design essays.', 'Contrast "austere absence" with "rigorous elimination of the superfluous".', 1.45, 0.5, 0.25, true, 0),
('ENG-78-UND-08', 'English Literacy', 'understanding', '7-8', 'advanced', '"The biographer refrains from hagiography; instead of casting the inventor as an infallible solitary genius, she chronicles his persistent intellectual indebtedness to overlooked laboratory assistants." What distinguishes this biography?', '[{"text":"It glorifies the inventor as an unassailable national hero beyond reproach.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"It demystifies the myth of isolated genius by documenting collaborative contributions and human limitations.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"It accuses the inventor of systematic scientific fraud and patent theft.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"It focuses exclusively on the commercial marketing of the finished products.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Identifying historiographical stance and biographical demystification.', 'Notice: "refrains from hagiography" (uncritical praise) and credits "overlooked assistants".', 1.5, 0.6, 0.25, true, 0),
('ENG-78-UND-09', 'English Literacy', 'understanding', '7-8', 'olympiad', '"The essayist argues that our modern obsession with continuous digital connectivity does not expand genuine communal intimacy; rather, it replaces deep, demanding interpersonal presence with frictionless, curated superficiality." What central diagnosis does the essayist offer?', '[{"text":"Computer networks should be dismantled to encourage postal letter correspondence.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Digital hyper-connection cultivates an illusion of closeness that actively undermines substantive, authentic human vulnerability.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Social media algorithms accurately measure psychological empathy among teenagers.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Frictionless communication has successfully eradicated global linguistic barriers.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Synthesizing sociological critique of contemporary digital epistemology.', 'Contrast "frictionless, curated superficiality" with "demanding interpersonal presence".', 1.6, 0.8, 0.25, true, 0),
('ENG-78-UND-10', 'English Literacy', 'understanding', '7-8', 'olympiad', '"When the narrator describes the ancient glacier as ''a slow, frozen tongue erasing the mountain''s memory with every century of descent,'' what dual existential impression is conveyed?"', '[{"text":"The rapid acceleration of alpine tourism in ski resorts.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The medical properties of sub-zero ice for preserving extinct mammoths.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The overwhelming geological timescale of nature alongside its inexorable power to pulverize historical landscapes.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"The acoustic properties of cracking ice shelf crevasses.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Interpreting sublime geological scale and poetic personification in literary essays.', 'Think about a glacier moving across centuries, literally wiping away the terrain.', 1.65, 0.9, 0.25, true, 0),
('ENG-78-LOC-01', 'English Literacy', 'locatingInformation', '7-8', 'standard', 'Space Mission Protocol: "During primary booster staging (T+142s), telemetry is routed to Ground Station Alice Springs. Failover telemetry automatically switches to Orbital Relay constellation Sigma only if primary latency exceeds 450 milliseconds for more than 1.2 seconds." Under what precise condition does failover engage?', '[{"text":"Only when primary telemetry latency exceeds 450 ms for more than 1.2 seconds.","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Immediately upon main engine ignition at T-0.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Whenever Ground Station Alice Springs undergoes scheduled antenna recalibration.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Only if booster staging occurs prior to T+100s.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Locating dual-condition technical thresholds in mission critical protocols.', 'Look for both the latency measurement (450 ms) and duration threshold (1.2 s).', 1.3, -0.2, 0.25, true, 0),
('ENG-78-LOC-02', 'English Literacy', 'locatingInformation', '7-8', 'standard', 'Civic Environmental Ordinance: "Section 12(B): Commercial entities generating over 50 kg of organic waste daily must contract with an authorized bio-methanation facility by June 30, 2027. Entities producing between 20 kg and 50 kg are granted an extension until December 31, 2028." What is the deadline for an entity generating 35 kg daily?', '[{"text":"June 30, 2027","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"December 31, 2028","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"January 1, 2026","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Immediate compliance upon receipt","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting categorized regulatory compliance deadlines based on numerical criteria.', 'Determine which category 35 kg falls into: between 20 kg and 50 kg.', 1.35, 0, 0.25, true, 0),
('ENG-78-LOC-03', 'English Literacy', 'locatingInformation', '7-8', 'standard', 'Scientific Laboratory Procedure: "To prevent thermal crystallization during titration: maintain reagent temperature strictly between 38°C and 42°C, introduce sodium citrate dropwise at a maximum rate of 0.5 mL/min, and agitate continuously at 250 RPM." What is the maximum permissible rate of sodium citrate addition?', '[{"text":"38°C","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"250 RPM","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"0.5 mL/min","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"42 mL/min","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting exact chemical delivery rates from multi-parameter laboratory manuals.', 'Search specifically for the reagent "sodium citrate" and its rate unit (mL/min).', 1.35, 0.1, 0.25, true, 0),
('ENG-78-LOC-04', 'English Literacy', 'locatingInformation', '7-8', 'standard', 'Historical Charter: "The Guild of Shipwrights ordained that apprentices must complete five full calendar years of drydock framing, execute one masterwork rib-joint unassisted, and pay forty silver shillings into the widows'' fund before obtaining freedom of trade." How many years of drydock framing were mandated?', '[{"text":"One year","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Forty years","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Five full calendar years","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Three calendar months","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Isolating specific durational requirements in historical institutional statutes.', 'Find the duration paired with "drydock framing".', 1.3, -0.1, 0.25, true, 0),
('ENG-78-LOC-05', 'English Literacy', 'locatingInformation', '7-8', 'standard', 'Volcanology Briefing: "The seismic array detected harmonic tremors at a focal depth of 6.4 km beneath Mount Merapi. Magmatic extrusion rates averaged 1.8 m³/s throughout August, rising to 3.5 m³/s following the tectonic swarm on September 3." What was the average extrusion rate throughout August?', '[{"text":"3.5 m³/s","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"1.8 m³/s","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"6.4 km","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"9 m³/s","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Scanning chronological geophysical reports for timeframe-specific rate metrics.', 'Distinguish between the August rate and the post-September rate.', 1.4, 0.1, 0.25, true, 0),
('ENG-78-LOC-06', 'English Literacy', 'locatingInformation', '7-8', 'advanced', 'Cybersecurity Whitepaper: "Under protocol TLS-Alpha, asymmetric handshakes utilize elliptic-curve Diffie-Hellman with 384-bit key lengths; session keys are regenerated every 60 minutes or after every 2 gigabytes of encrypted payload transfer, whichever threshold is breached first." What are the two trigger conditions for session key regeneration?', '[{"text":"Only upon an explicit brute-force intrusion notification.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Every 384 seconds OR whenever key length drops below 128 bits.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Whenever a client disconnects from the VPN gateway.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Every 60 minutes elapsed OR after 2 gigabytes of payload transfer.","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Extracting dual-threshold trigger mechanisms from network security specifications.', 'Notice the phrase: "whichever threshold is breached first".', 1.45, 0.3, 0.25, true, 0),
('ENG-78-LOC-07', 'English Literacy', 'locatingInformation', '7-8', 'advanced', 'Pharmacological Monograph: "Bioavailability of Compound Z is 68% when ingested fasting, but decreases to 34% when co-administered with divalent cations such as magnesium or calcium. Peak plasma concentration (Cmax) is achieved at 1.5 hours post-dose." What factor halves Compound Z''s bioavailability?', '[{"text":"Ingestion in a strictly fasting state with pure distilled water.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Co-administration with divalent cations like magnesium or calcium.","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Administering the compound at 1.5-hour intervals.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Elevating plasma concentration above 68%.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Identifying specific biochemical inhibitors and conditions in clinical literature.', 'Compare 68% fasting to 34% when taken with certain minerals.', 1.5, 0.4, 0.25, true, 0),
('ENG-78-LOC-08', 'English Literacy', 'locatingInformation', '7-8', 'advanced', 'Antarctic Meteorological Dossier: "At Dome Concordia (Elevation 3,233 m), the lowest surface air temperature recorded was -84.6°C on September 3, 2017. Average katabatic wind speeds during the polar night reach 28 knots, with sustained gusts exceeding 65 knots during polar vortex incursions." What was the record low temperature?', '[{"text":"-84.6°C","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"3,233 m","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"-65°C","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"28 knots","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Isolating specific historical extremes within dense climatological records.', 'Scan for the temperature unit (°C) and the word "lowest".', 1.45, 0.2, 0.25, true, 0),
('ENG-78-LOC-09', 'English Literacy', 'locatingInformation', '7-8', 'olympiad', 'Maritime Legal Judgment: "The Tribunal ruled that under Clause 14.3 of the Charterparty, demurrage accrues at $15,000 per running day pro rata, commencing exactly 12 hours after the Master tenders Notice of Readiness (NOR), unless port closure is formally declared by the Sovereign Authority." When does demurrage begin to accrue?', '[{"text":"Only after 15,000 running hours have elapsed since bill of lading issuance.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Immediately upon dropping anchor in the outer harbor roadstead.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Exactly 12 hours after the Master tenders Notice of Readiness, absent sovereign port closure.","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"When the Sovereign Authority approves cargo customs manifestos.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting precise contractual timelines and legal exception clauses.', 'Locate the exact delay period following the NOR tender.', 1.6, 0.7, 0.25, true, 0),
('ENG-78-LOC-10', 'English Literacy', 'locatingInformation', '7-8', 'olympiad', 'Genetic Sequencing Field Report: "Amplification of the cytochrome c oxidase subunit I (COI) barcode locus required an initial denaturation phase of 95°C for 3 minutes, followed by 35 cycles of 94°C (30s), 52°C (40s), and 72°C (1 min). What was the annealing temperature during the 35 cycles?', '[{"text":"95°C","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"52°C","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"94°C","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"72°C","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Scanning complex PCR cycling protocols for the intermediate annealing temperature.', 'In standard 3-step PCR (denature, anneal, extend), annealing is the middle temperature.', 1.65, 0.8, 0.25, true, 0)
